  box-shadow: var(--bubble-them-shadow) !important;
  color: #a08c96 !important; 
}
.msg-them .voice-transcription {
  background: var(--bubble-me-bg) !important;
  box-shadow: var(--bubble-me-shadow) !important;
  color: #a08c96 !important; 
}

/* ---------- B. 引用分离 ---------- */
.msg-reply-block { display: none !important; }
.msg-reply-block-detached { display: flex !important; }

/* ---------- C. 翻译分离 ---------- */
.msg-translation-wrapper { display: none !important; }
.msg-translation-detached {
  display: flex !important;
  margin-top: 6px !important; 
  width: fit-content !important;
  max-width: 100% !important;
}
.msg-translation-detached-me { align-self: flex-end !important; }
.msg-translation-detached-them { align-self: flex-start !important; }
.msg-translation-detached-content {
