  box-shadow: var(--bubble-them-shadow) !important;
}
.msg-translation-detached-them .msg-translation-detached-content {
  background: var(--bubble-me-bg) !important; 
  color: #a08c96 !important;
  box-shadow: var(--bubble-me-shadow) !important;
}

.msg-translation-detached-content::before,
.msg-translation-detached-content::after {
  content: none !important;
  display: none !important;
}

/* ============================================
   底栏排版与贴纸
============================================ */
.input-area-custom {
  position: relative !important;
  margin: 0 !important; 
  border-radius: 0 !important; 
  width: 100% !important;
}

.input-btn-plus {
  transform: translateY(-8px) !important; 
  width: 28px !important;
  height: 28px !important;
  background-size: 22px 22px !important;
}

.input-area-custom::before {
  content: "";
  position: absolute;
  top: -28px;
  left: 20px;
  width: 44px;
  height: 36px;
  background-image: url('https://i.postimg.cc/cCrkpNhj/1786155676584.png');
  background-size: contain;
  background-position: bottom left;
  background-repeat: no-repeat;
  pointer-events: none;
  z-index: 10;
}

@keyframes sendSpin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

/* ============================================
   气泡与旁白贴纸
============================================ */
.msg-narration-custom {
  position: relative !important;
  overflow: visible !important;
  margin: 24px auto 12px !important;
}
.msg-narration-custom::after {
  content: "";
  position: absolute;
  top: -30px;
  left: 50%;
  transform: translateX(-50%);
  width: 48px;
  height: 38px;
  background-image: url('https://i.postimg.cc/6qXTS9Bx/1786086039172.png');
  background-size: contain;
  background-position: bottom center;
  background-repeat: no-repeat;
  pointer-events: none;
  z-index: 10;
}

.bubble-me-custom, .bubble-them-custom {
  position: relative !important;
  overflow: visible !important;
}

/* 对方常规气泡贴纸 */
.bubble-them-custom::before {
  content: "";
  position: absolute;
  top: -20px;       
  right: -22px;     
  width: 42px;      
  height: 42px;     
  background-image: url('https://i.postimg.cc/5yVjGxfV/1786086032668.png');
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
  pointer-events: none;
  z-index: 10;
}

/* 己方常规气泡贴纸 */
.bubble-me-custom::before {
  content: "";
  position: absolute;
  bottom: -18px; 
  left: -16px;
  width: 38px;
  height: 38px;
  background-image: url('https://i.postimg.cc/qqTgYkpp/1786085880827.png');
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
  pointer-events: none;
  z-index: 10;
}

/* 屏蔽分离式外壳的贴纸 */
.msg-them .bubble-them-custom:has(.voice-msg)::before,
.msg-me .bubble-me-custom:has(.voice-msg)::before {
  display: none !important;
}
/* ============================================
   补丁：通用隔离法与完美缩小 (天才思路版)
============================================ */

/* 1. 通用反向隔离 (你的绝妙巧思)
   只要气泡内包含图片(img)、卡片组件(card)、语音(voice)，一律强行杀掉小狗和CHAR挂件素材！
   再也不用一个个写死类名了！ */
.bubble-me-custom:has(img)::before,
.bubble-them-custom:has(img)::before,
.bubble-me-custom:has([class*="card"])::before,
.bubble-them-custom:has([class*="card"])::before,
.bubble-me-custom:has(.voice-msg)::before,
.bubble-them-custom:has(.voice-msg)::before {
  display: none !important;
  content: none !important;
  background-image: none !important;
}

/* 扒掉这些特殊气泡的自带白底色和边框，只留内部本体 */
.bubble-me-custom:has(img),
.bubble-them-custom:has(img),
.bubble-me-custom:has([class*="card"]),
.bubble-them-custom:has([class*="card"]) {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}

/* 2. 修复图片/文字图缩放：精准定位直接约束宽度 */
.msg-image-wrapper,
.bubble-me-custom.image,
.bubble-them-custom.image {
  max-width: 140px !important; /* 强制缩小极限尺寸 */
  border-radius: 12px !important;
  box-shadow: 0 2px 8px rgba(240, 224, 232, 0.4) !important;
  overflow: hidden !important;
}
.msg-image-wrapper img,
.bubble-me-custom.image img,
.bubble-them-custom.image img {
  width: 100% !important;
  height: auto !important;
  border-radius: 12px !important;
  display: block !important;
}

/* 3. 修复表情包：剥离阴影与圆角，保证边缘透明感 */
.bubble-me-custom.sticker,
.bubble-them-custom.sticker,
.bubble-me-custom:has(.emoji), 
.bubble-them-custom:has(.emoji) {
  max-width: 100px !important; /* 表情包压得比普通图片更小 */
  background: transparent !important;
  box-shadow: none !important;
  border-radius: 0 !important;
}
.bubble-me-custom.sticker img,
.bubble-them-custom.sticker img {
  width: 100% !important;
  height: auto !important;
}

/* 4. 修复卡片悬空与变远问题：使用自动布局收缩的 zoom 属性 */
.msg-transfer-card,
.msg-redpacket-card,
.msg-loc-card,
[class*="card"] {
  zoom: 0.85 !important; /* 核心魔法：缩小的同时完美自适应占位，绝不会悬空远离头像 */
  border-radius: 16px !important;
  box-shadow: 0 2px 10px rgba(240, 224, 232, 0.4) !important;
  overflow: hidden !important;
}

/* 兼容部分不支持 zoom 的安卓底层（双保险） */
@supports not (zoom: 0.85) {
  .msg-transfer-card,
  .msg-redpacket-card,
  .msg-loc-card,
  [class*="card"] {
    transform: scale(0.85) !important;
  }
  .msg-me [class*="card"] {
    transform-origin: right center !important;
    margin-right: -5% !important; /* 拉近与我方头像的距离 */
  }
  .msg-them [class*="card"] {
    transform-origin: left center !important;
    margin-left: -5% !important; /* 拉近与对方头像的距离 */
  }
}

